// Evaluate KPI Thresholds Against Configured Governance Targets
const data = $input.first().json;

const thresholds = {
  min_repeat_purchase_rate: 3.5,
  max_delayed_deliveries_pct: 8.0,
  min_delayed_csat: 3.0
};

const breaches = [];

if (data.repeat_purchase_rate_pct < thresholds.min_repeat_purchase_rate) {
  breaches.push({
    metric: 'Repeat Purchase Rate (%)',
    actual: data.repeat_purchase_rate_pct,
    threshold: thresholds.min_repeat_purchase_rate,
    severity: 'WARNING',
    note: 'Repeat purchase rate is below 3.5% target.'
  });
}

if (data.delayed_deliveries_pct > thresholds.max_delayed_deliveries_pct) {
  breaches.push({
    metric: 'Delayed Deliveries (%)',
    actual: data.delayed_deliveries_pct,
    threshold: thresholds.max_delayed_deliveries_pct,
    severity: 'CRITICAL',
    note: 'Logistics SLA breached; delayed deliveries exceed 8.0%.'
  });
}

if (data.delayed_avg_review_score < thresholds.min_delayed_csat) {
  breaches.push({
    metric: 'Delayed Order CSAT Rating',
    actual: data.delayed_avg_review_score,
    threshold: thresholds.min_delayed_csat,
    severity: 'CRITICAL',
    note: 'Customer review rating for late orders has collapsed below 3.0 stars.'
  });
}

return [{
  json: {
    alert_triggered: breaches.length > 0,
    total_breaches: breaches.length,
    breaches: breaches,
    metrics: data,
    audit_timestamp: new Date().toISOString()
  }
}];

const alert = $input.first().json;

return [{
  json: {
    notification_channel: 'slack_or_email',
    subject: `🚨 [RETENTION ALERT] ${alert.total_breaches} Governance Breaches Detected`,
    body: `Retention and Logistics Audit identified ${alert.total_breaches} metric threshold breaches at ${alert.audit_timestamp}.\n\n` +
          alert.breaches.map(b => `• [${b.severity}] ${b.metric}: Actual = ${b.actual} vs Target = ${b.threshold}. ${b.note}`).join('\n') + 
          `\n\nAction: Triggering automated mitigation and notifying Retention Marketing & Logistics Ops.`,
    severity: 'HIGH'
  }
}];

return [{
  json: {
    notification_channel: 'slack_or_email',
    subject: '✅ [RETENTION OK] All Customer Retention & Logistics Metrics Compliant',
    body: 'All monitored customer retention, AOV, and logistics metrics are within healthy target thresholds.',
    severity: 'INFO'
  }
}];
